import{_ as a,o as r,c as t,a6 as i}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"TikTools 4.2.1-rc.1 候选版记录","description":"","frontmatter":{"title":"TikTools 4.2.1-rc.1 候选版记录","docId":"releases.4.2.1-rc.1","translationKey":"releases.4.2.1-rc.1","locale":"zh","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"f2b9e975511584a1a6156af8326d7603d73be54f10c97d7e46ed385def4755f6","translationRevision":"748c60fa79eaaa9e6e7bf40e2bf32f398a5858657740e8f4bc4315cf193f1ed8","order":10},"headers":[],"relativePath":"zh/releases/4.2.1-rc.1.md","filePath":"zh/releases/4.2.1-rc.1.md","lastUpdated":1794611623000}'),o={name:"zh/releases/4.2.1-rc.1.md"};function l(s,e,c,n,d,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="tiktools-421-rc1" tabindex="-1">TikTools 4.2.1-rc.1 候选版记录 <a class="header-anchor" href="#tiktools-421-rc1" aria-label="Permalink to &quot;TikTools 4.2.1-rc.1 候选版记录 {#tiktools-421-rc1}&quot;">​</a></h1><h2 id="goal-status-and-prerequisites" tabindex="-1">目标、状态与前置条件 <a class="header-anchor" href="#goal-status-and-prerequisites" aria-label="Permalink to &quot;目标、状态与前置条件 {#goal-status-and-prerequisites}&quot;">​</a></h2><p>本篇历史候选版记录可用于复现 RC1 调查的 Cloud 恢复、团队和 Linux AppImage 问题。它描述应用基线 <code>338495a9</code> 及独立后端基线 <code>6a69c99</code>，不能证明 RC1 下载目前仍可用。选择安装器前，请检查<a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">已发布资源</a>。</p><p>当时 Actions 被禁用，记录中的候选版使用本地构建的 Linux AppImage、DEB 和便携包，不含新构建的 Windows 安装器。迁移测试请保留备份，并隔离复制受影响配置。协作和 Cloud 分区恢复仍属实验性功能。</p><h2 id="changes-in-this-candidate" tabindex="-1">此候选版的变化 <a class="header-anchor" href="#changes-in-this-candidate" aria-label="Permalink to &quot;此候选版的变化 {#changes-in-this-candidate}&quot;">​</a></h2><ul><li>设置保留账户/会话及诊断；插件管理其目录、搜索、更改和安装操作。模板与配置仍位于自动化。</li><li>共享更改面板区分比较失败与成功的空结果。插件分区发送自己的选择/设置，同时保留其他队列及缓存下载。</li><li>迁移容忍缺少隐式内置插件目录，对明确配置的路径保持严格，并指出缺失包 ID 以供审查修复。待处理编辑和冲突均会保留。</li><li>团队区分将当前电脑注册为宿主与选择另一台电脑上的宿主。昵称邀请绑定选定收件人，仍需宿主批准。</li><li>可选引导帮助跟随设置状态。Linux 打包包含 WebKit 辅助程序、GStreamer 插件及扫描器，供后续媒体检查。</li></ul><h2 id="reproduce-and-inspect-the-expected-result" tabindex="-1">复现并检查预期结果 <a class="header-anchor" href="#reproduce-and-inspect-the-expected-result" aria-label="Permalink to &quot;复现并检查预期结果 {#reproduce-and-inspect-the-expected-result}&quot;">​</a></h2><ol><li>记录显示版本和操作系统。打开插件 → 更改，加载失败时保留确切错误及请求 ID。</li><li>在复制的配置中预览迁移，修复前审查确切的缺失包 ID。之后再次预览；待处理编辑及冲突应仍然存在。</li><li>在团队中，先注册当前电脑再测试开始控件。选择另一台电脑的宿主不应授权启动本机。</li><li>先检查 AppImage 启动，再分别检查音频/视频。仅到达前端不能证明媒体播放成功。</li></ol><p>昵称搜索和绑定收件人的邀请，需要后端 <code>6a69c99</code> 及迁移 <code>20261113000001_remote_invitation_recipients.sql</code>。安装此候选版不会部署该后端。</p><h2 id="recovery-and-evidence-limits" tabindex="-1">恢复与证据限制 <a class="header-anchor" href="#recovery-and-evidence-limits" aria-label="Permalink to &quot;恢复与证据限制 {#recovery-and-evidence-limits}&quot;">​</a></h2><p>比较失败时，保留原生原因，并通过受支持面板重试。不要删除待处理状态，也不要从兼容性检查推断迁移成功。按<a href="./../user/preferences/troubleshooting.html">故障排查指南</a>收集版本、操作及脱敏诊断详情。</p><p>原始记录报告了其基线上的前端、同步引擎、收件人隔离和双宿主原生/中继检查。这些有日期的检查不是最新生产验证。历史 SQLite 锁持有者未被识别。RC1 时，变量和叠加层 Cloud 适配器尚未完成，自动化比较本地参考。后续范围请阅读<a href="./4.2.1-rc.3.html">后来的候选版说明</a>及<a href="./../user/cloud/changes.html">当前变更指南</a>。</p><p><a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.1.md" target="_blank" rel="noreferrer">原始发布记录</a>作为带日期证据保留。返回<a href="./">发行说明索引</a>。</p>',13)])])}const f=a(o,[["render",l]]);export{u as __pageData,f as default};
